package com.quincaisoft.company.application;import com.quincaisoft.company.api.*;import com.quincaisoft.company.infrastructure.*;import com.quincaisoft.shared.*;import jakarta.persistence.*;import org.springframework.stereotype.Service;import java.util.*;@Service public class DefaultCompanyService implements CompanyService{private final EntityManager em;private final ScopedTransactions tx;public DefaultCompanyService(EntityManager em,ScopedTransactions tx){this.em=em;this.tx=tx;}public void requireSingleBranchCompany(){tx.execute(()->{var scope=TenantContext.current();var company=em.find(CompanyEntity.class,new CompanyEntity.Key(scope.tenantId(),scope.companyId()),LockModeType.PESSIMISTIC_READ);if(company==null||company.branchCount!=1)throw new IllegalStateException("Company-wide close requires dedicated multi-branch authority; only single-branch companies are supported here");return null;});}public List<Item> list(){return tx.execute(()->em.createQuery("select r from CompanyEntity r order by r.name,r.id",CompanyEntity.class).getResultList().stream().map(r->new Item(r.id,r.name)).toList());}}